class Solution {
public:
    int maxEqualFreq(std::vector<int>& nums) {
        std::unordered_map<int, int> count, freq;
        int maxF = 0, ans = 0;
        for (int i = 0; i < nums.size(); ++i) {
            int x = nums[i];
            if (count[x] > 0) freq[count[x]]--;
            count[x]++;
            freq[count[x]]++;
            maxF = std::max(maxF, count[x]);

            if (maxF == 1) {
                ans = i + 1;
            } else if (freq[maxF] * maxF + 1 == i + 1 && freq[1] == 1) {
                ans = i + 1;
            } else if (freq[maxF] == 1 && (freq[maxF - 1] + 1) * (maxF - 1) + 1 == i + 1) {
                ans = i + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxEqualFreq(int[] nums) {
        java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
        java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
        int maxF = 0, ans = 0;
        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];
            int c = count.getOrDefault(x, 0);
            if (c > 0) freq.put(c, freq.get(c) - 1);
            count.put(x, c + 1);
            freq.put(c + 1, freq.getOrDefault(c + 1, 0) + 1);
            maxF = Math.max(maxF, c + 1);

            if (maxF == 1) {
                ans = i + 1;
            } else if (freq.getOrDefault(maxF, 0) * maxF + 1 == i + 1 && freq.getOrDefault(1, 0) == 1) {
                ans = i + 1;
            } else if (freq.getOrDefault(maxF, 0) == 1 && (freq.getOrDefault(maxF - 1, 0) + 1) * (maxF - 1) + 1 == i + 1) {
                ans = i + 1;
            }
        }
        return ans;
    }
}

var maxEqualFreq = function(nums) {
    const count = new Map(), freq = new Map();
    let maxF = 0, ans = 0;
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        const c = count.get(x) || 0;
        if (c > 0) freq.set(c, (freq.get(c) || 0) - 1);
        count.set(x, c + 1);
        freq.set(c + 1, (freq.get(c + 1) || 0) + 1);
        maxF = Math.max(maxF, c + 1);

        if (maxF === 1) {
            ans = i + 1;
        } else if ((freq.get(maxF) || 0) * maxF + 1 === i + 1 && (freq.get(1) || 0) === 1) {
            ans = i + 1;
        } else if ((freq.get(maxF) || 0) === 1 && ((freq.get(maxF - 1) || 0) + 1) * (maxF - 1) + 1 === i + 1) {
            ans = i + 1;
        }
    }
    return ans;
};
